import java.util.*;

public class Main {
    public static void main(String[] args) {
        Map<String, Integer> fruitInventory = new LinkedHashMap<>();
        fruitInventory.put("Apples", 50);
        fruitInventory.put("Bananas", 30);
        fruitInventory.put("Oranges", 50);

        System.out.println("Keys (Set): " + fruitInventory.keySet());
        System.out.println("Values (Collection): " + fruitInventory.values());

        int sum = 0;
        for (int qty : fruitInventory.values()) {
            sum += qty;
        }
        System.out.println("Total Value Sum: " + sum);
        System.out.println("Total Entries: " + fruitInventory.entrySet().size());
    }
}

